# Grade C7 (pass 20): IFEval-style checkers for untested format types, NC combos, math (last boxed) and MC (last 'answer is (X)'); paired v4 - start.
import re
G20s, G20e = loadg('/work/gen_20_start.jsonl'), loadg('/work/gen_20_edited.jsonl')
def ck(inst, v):
    t = inst['type']
    if t == 'json':
        x = v.strip().removeprefix('```json').removeprefix('```Json').removeprefix('```JSON').removeprefix('```').removesuffix('```').strip()
        try: json.loads(x); return True
        except Exception: return False
    if t in ('end_nc', 'end_c'): return v.strip().lower().endswith(inst['phrase'].strip().lower())
    if t == 'postscript': return bool(re.findall(r"\s*p\.\s?s\..*$", v.lower(), flags=re.MULTILINE))
    if t == 'title': return any(x.lstrip('<').rstrip('>').strip() for x in re.findall(r"<<[^\n]+>>", v))
    if t == 'placeholders': return len(re.findall(r"\[.*?\]", v)) >= inst['N']
    if t == 'bullets': return len(re.findall(r"^\s*\*[^\*].*$", v, flags=re.MULTILINE)) + len(re.findall(r"^\s*-.*$", v, flags=re.MULTILINE)) == inst['N']
    if t == 'sections': return len(re.split(r"\s?SECTION\s?\d+\s?", v)) - 1 >= inst['N']
    if t == 'quotation': v = v.strip(); return len(v) > 1 and v[0] == '"' and v[-1] == '"'
    if t == 'two_resp':
        parts = v.split('******'); val = []
        for i, p in enumerate(parts):
            if not p.strip():
                if i != 0 and i != len(parts) - 1: return False
            else: val.append(p)
        return len(val) == 2 and val[0].strip() != val[1].strip()
    if t == 'no_comma': return ',' not in v
    raise ValueError(t)
def last_boxed(s):
    i = s.rfind('\\boxed{')
    if i < 0: return None
    j, d, out = i + 7, 1, []
    while j < len(s):
        c = s[j]; d += (c == '{') - (c == '}')
        if d == 0: break
        out.append(c); j += 1
    return ''.join(out)
def norm(x): return re.sub(r"[\s$,]|\\!|\\,|\\text\{|\}", '', x or '')
rowsI, prS, prE, mS, mE, qS, qE = [], [], [], [], [], [], []
for k, m in enumerate(C7):
    a_s, a_e = ans_of(G20s[f'prompt/{k}']['text']) or '', ans_of(G20e[f'prompt/{k}']['text']) or ''
    if m['kind'] == 'if':
        hasnc = any(i['type'] == 'no_comma' for i in m['insts'])
        ss = [ck(i, a_s) for i in m['insts']]; ee = [ck(i, a_e) for i in m['insts']]
        for i, s, e in zip(m['insts'], ss, ee): rowsI.append((i['type'], hasnc and i['type'] != 'no_comma', int(s), int(e)))
        prS.append(all(ss)); prE.append(all(ee))
    elif m['kind'] == 'math':
        mS.append(norm(last_boxed(a_s)) == norm(m['ans'])); mE.append(norm(last_boxed(a_e)) == norm(m['ans']))
    else:
        fs = re.findall(r"answer is \(?([A-J])\)?", a_s, flags=re.I); fe = re.findall(r"answer is \(?([A-J])\)?", a_e, flags=re.I)
        qS.append(bool(fs) and fs[-1].upper() == m['ans']); qE.append(bool(fe) and fe[-1].upper() == m['ans'])
